mapper.select:
select

from vm_timeline_info t

    and t.delete_flag = 0
    ${dataScope}

        and t.timeline_name like concat('%',#{timelineName, jdbcType=VARCHAR},'%')



        and t.create_time >= #{createTimeStart, jdbcType=TIMESTAMP}


        and t.create_time <= #{createTimeEnd, jdbcType=TIMESTAMP}



        and t.update_time >= #{updateTimeStart, jdbcType=TIMESTAMP}


        and t.update_time <= #{updateTimeEnd, jdbcType=TIMESTAMP}



        and t.creator like concat('%',#{creator, jdbcType=VARCHAR},'%')



        and t.modifier like concat('%',#{modifier, jdbcType=VARCHAR},'%')


order by CASE WHEN t.sort_num IS NULL THEN 1 ELSE 0 END ASC,t.sort_num asc,t.update_time desc,t.create_time desc

select t.timeline_name, d.timeline_detail_id, d.timeline_id, d.layer, d.layer_name, d.layer_namespace, d.`year`, d.`month`, d.`day`, d.sort_num, d.geo_type, d.root_geoserver_url, d.custom_name, d.maxx, d.maxy, d.minx, d.miny, d.stay_time, d.industry_code, d.app_ver_code, d.tenant_id, d.tenant_name, d.create_time, d.update_time, d.creator, d.modifier, d.delete_flag, d.category, d.fileUrl from vm_timeline_detail d left join vm_timeline_info t on d.timeline_id = t.timeline_id
and t.delete_flag = 0 and d.delete_flag = 0 ${dataScope}
and t.timeline_id = #{timelineId}
and t.timeline_name like concat('%',#{timelineName},'%')
order by t.create_time desc, d.sort_num asc

mapper.update:
update vm_timeline_info
set delete_flag = 1, update_time = now()
where timeline_id = #{timelineId}

update vm_timeline_info
set sort_num = sort_num + 1
where delete_flag = 0

    and sort_num >= #{start}


    and sort_num <= #{end}


    and timeline_id != #{excludeId}

${data.dataScope}

update vm_timeline_info
set sort_num = sort_num - 1
where delete_flag = 0

    and sort_num >= #{start}


    and sort_num <= #{end}


    and timeline_id != #{excludeId}

${data.dataScope}

update vm_timeline_info


        sort_num = #{updateInfo.sortNum},


where timeline_id = #{updateInfo.timelineId}
and delete_flag = 0
${data.dataScope}
